import { OrderRepository, parseCursor } from './repository';
import { ListRequest, Page } from './types';

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}

  list(request: ListRequest): Page {
    const { tenant, limit, cursor } = request;
    if (!tenant || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new Error('invalid request');
    }
    if (cursor !== undefined) {
      parseCursor(cursor);
    }
    return this.repository.listPage(tenant, limit, cursor);
  }
}

